'use strict';
const elves=EldoriaElvesModel,elfPopulation=elves.residents(cityResidents);elves.ensure(state);
const elfCSS=document.createElement('link');elfCSS.rel='stylesheet';elfCSS.href='city-elves.css?v=1';document.head.append(elfCSS);
const elfLayer=document.createElement('div');elfLayer.id='elfNeighbors';elfLayer.setAttribute('aria-label','Elves you can meet here');$('citySceneWorld').append(elfLayer);
let elfLastView='',elfVisible=[];
function elfSpriteStyle(el,person){const cell=person.sprite%6;el.style.backgroundImage='url("assets/characters/elf-residents-'+(person.sprite<6?'a':'b')+'.webp")';el.style.backgroundSize='300% 200%';el.style.backgroundPosition=(cell%3*50)+'% '+(cell>2?'100%':'0%')}
function elfDiverse(list,n){const used=new Set(),out=[];for(const e of list)if(!used.has(e.sprite)){used.add(e.sprite);out.push(e)}return out.slice(0,n)}
function elfHere(){const c=atmosphere.conditions(state),local=elfPopulation.filter(e=>e.district===scene||e.districts?.includes(scene));if(!cityInside||cityInside==='willowLane')return elfDiverse([...local.filter(e=>e.featured),...local.filter(e=>!e.featured)],4);const h=neighborhood.home(cityInside);if(h)return neighborhood.present(h.id,c)?elfPopulation.filter(e=>e.id===elves.key(h.person)):[];if(cottageRoom(cityInside)||['home','legacyRoom'].includes(cityInside)){if(cityInside==='cottageSitting'&&state.cityCottage?.completed[c.key+':visit'])return elfPopulation.filter(e=>e.name==='Pip');return[]}if(cityTreehousePorch)return local.slice(0,1);if(cityInside==='countyCamp')return elfPopulation.filter(e=>['Willow','Keeper Willow','Aurelia','Pip'].includes(e.name)).slice(0,3);return elfDiverse([...local.filter(e=>e.featured),...local.filter(e=>!e.featured)],2)}
function elfTalk(id,travel=false){const person=elfPopulation.find(e=>e.id===id);if(!person)return;if(travel&&scene!==person.district){$('modal').close();changeScene(person.district)}modal(person.name+' · '+person.role,'<div id="elfPortrait" class="elf-dialogue-portrait" role="img" aria-label="'+lifeEsc(person.name)+' the elf"></div><p class="life-dialogue">“'+lifeEsc(person.line)+'”</p><p id="elfGreeting" role="status">Friendship: '+(elves.ensure(state).friends[person.id]||0)+'</p>');elfSpriteStyle($('elfPortrait'),person);action('Share a conversation',()=>{const r=elves.greet(state,person,lifeWhere(),atmosphere.conditions(state));if(r.ok){lifeCommit();$('elfGreeting').textContent=r.title+'. Your friendship is saved.'}else $('elfGreeting').textContent=r.reason});const core=cityLife.people.find(p=>elves.key(p.name)===person.id);if(core)action('Visit '+person.name+' at work',()=>lifeFriend(core.id));const home=neighborhood.homes.find(h=>elves.key(h.person)===person.id);if(home)action('Visit '+person.name+'’s cottage',()=>{$('modal').close();neighborhoodVisit(home.id)});action('Back to Eldoria',()=>{$('modal').close();cityDraw()})}
function elfDirectory(){modal('The elves of Eldoria','<p>'+elfPopulation.length+' neighbors live, work and gather across Eldoria. Choose someone to visit their district and meet them.</p><div id="elfDirectory"></div>');for(const district of cityRoute){const group=document.createElement('section'),h=document.createElement('h3');h.textContent=cityShort[district];group.append(h);for(const person of elfPopulation.filter(e=>e.district===district)){const b=document.createElement('button');b.className='elf-directory-person';const pic=document.createElement('span');pic.className='elf-directory-sprite';pic.setAttribute('aria-hidden','true');elfSpriteStyle(pic,person);const name=document.createElement('span');name.textContent=person.name+' · '+person.role;b.append(pic,name);b.onclick=()=>elfTalk(person.id,true);group.append(b)}$('elfDirectory').append(group)}}
const elfButton=document.createElement('button');elfButton.id='elfMeetEveryone';elfButton.textContent='Meet the elves';elfButton.onclick=elfDirectory;lifeBar.append(elfButton);
function elfDraw(){const people=elfHere(),key=scene+':'+cityInside+':'+people.map(p=>p.id).join(',')+':'+(innerWidth<600);if(key!==elfLastView){elfLastView=key;elfLayer.replaceChildren();elfVisible=people.slice(0,innerWidth<600?2:4);const positions=elfVisible.length===1?[42]:scene==='home'&&!cityInside?(elfVisible.length===2?[24,53]:elfVisible.length===3?[16,35,54]:[12,27,42,56]):elfVisible.length===2?[30,73]:elfVisible.length===3?[20,50,80]:[17,39,63,85];elfVisible.forEach((person,i)=>{const b=document.createElement('button');b.className='elf-neighbor';b.dataset.elf=person.id;b.setAttribute('aria-label','Talk to '+person.name+' the elf');b.style.left=positions[i]+'%';b.style.top=72+(i%2?1:0)+'%';b.style.setProperty('--elf-delay',(-i*1.1)+'s');const art=document.createElement('span');art.className='elf-figure';art.setAttribute('aria-hidden','true');elfSpriteStyle(art,person);const name=document.createElement('span');name.className='elf-name';name.textContent=person.name;b.append(art,name);b.onclick=()=>elfTalk(person.id);elfLayer.append(b)})}$('cityScene').dataset.elvesVisible=String(elfVisible.length>0);const size=Math.max(140,Math.min(innerWidth<600?160:205,$('cityScene').clientHeight*.28));elfLayer.style.setProperty('--elf-size',size+'px');for(const b of $('cityPeople').querySelectorAll('.city-person')){const name=b.querySelector('strong')?.textContent||b.textContent,person=elfPopulation.find(e=>name.startsWith(e.name));if(!person)continue;let avatar=b.querySelector('.city-person-avatar,.elf-avatar');if(!avatar){avatar=document.createElement('span');b.prepend(avatar)}avatar.textContent='';avatar.className='elf-avatar';avatar.setAttribute('aria-hidden','true');elfSpriteStyle(avatar,person)}}
const elfDrawBefore=cityDraw;cityDraw=function(){elfDrawBefore();elfDraw()};comfortDraw=cityDraw;
const elfResize=new ResizeObserver(()=>elfDraw());elfResize.observe($('cityScene'));window.addEventListener('resize',elfDraw);
window.ELDORIA_ELVES={version:1,get population(){return elfPopulation.map(p=>({...p}))},get visible(){return elfVisible.map(p=>({...p}))},openDirectory:elfDirectory};elfDraw();persist();
